-- GENERATED by `wfj generate` from data/gossip/gossip-b4.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["b400abff494d98db"] = { "State indietro! I bambini non dovrebbero stare qui! Via di qui, piccolo!", "." },
  ["b405b84c158241bf"] = { "Se vuoi diventare Fabbro di Spade, basta chiedere.", "." },
  ["b408ed483824c61e"] = { "Ma ora, molti anni dopo, i silvagufi sono diventati più selvaggi e, senza la guida della dea, sono confusi...", "." },
  ["b40b5bc6f81fa78a"] = { "Neltharion è la mia risposta.", "." },
  ["b41214626ebf1548"] = { "Come posso dimostrare il mio valore ai mezzorsi Mordilegno?", "." },
  ["b41999238596dee1"] = { "Ecco la classifica finale!\n\nThrall: $2200w\n\nCairne: $2201w\n\nSylvanas: $2202w\n\nTotale ⟦Horde=Orda⟧: $2207w\n\nBolvar: $2203w\n\nMagni: $2204w\n\nTyrande: $2205w\n\nTotale ⟦Alliance=Alleanza⟧: $2206w\n\nL'eroe più popolare è dell'⟦Alliance=Alleanza⟧!", "." },
  ["b41a59e75513f6fb"] = { "Centinaia di anni fa, la grande città di Thaurissan sorgeva fiera in una rigogliosa distesa di terre che oggi sono le desolate ⟦Burning Steppes=Steppe Ardenti⟧.\n\nThaurissan era la patria della nazione dei nani ⟦Dark Iron=Ferroscuro⟧ e, a quel tempo, era nel mezzo di una guerra civile con il resto della nazione dei nani.\n\nVedi, quella zona del mondo un tempo faceva parte delle ⟦Redridge Mountains=Montagne Crestarossa⟧, fino al giorno in cui Thaurissan fu consumata da un'esplosione gigantesca. La città rimase in rovina, e le aree circostanti furono ridotte a una landa di cenere.", "." },
  ["b41f64a0a3bbb72f"] = { "Raze seguire {name}! Raze SPACCARE bracconieri! SPACCA SPACCA SPACCA! Di' a Raze di SPACCARE giocando con bastone! SPACCA!", "." },
  ["b421a96b431ef611"] = { "Ah ah! Alterac e ⟦Hillsbrad=Colletorto⟧ torneranno sotto il nostro legittimo dominio, ora che il magistrato è caduto. Ritirata!", "." },
  ["b42a8749b20af128"] = { "I fantasmi degli ⟦Highborne=Alti Nobili⟧ che vedi vagare per il cortile e le sale di Eldre'Thalas non sono stati uccisi dagli ogre Gordok invasori o dai satiri, ma dal principe in persona!", "." },
  ["b434525af5ee8ad3"] = { "L'oscurità che circonda le nostre terre ti metterà alla prova molte volte, {name}. Ma perché tu sia sempre <pronto/pronta>, ti affideremo spesso dei compiti, così sarai al culmine delle tue forze.\n\nVa' con la Luce, e non abbandonare la virtù.", "." },
  ["b4366fdf1c8b1eca"] = { "La ⟦Irondeep Mine=Miniera di Ferrofondo⟧ è in territorio dell'⟦Alliance=Alleanza⟧, a nord del ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧.\n\nÈ controllata dall'⟦Horde=Orda⟧.", "." },
  ["b43c1330ec1b61d0"] = { "Guarda quante increspature. C'è molta attività nell'acqua, quindi oggi dovrei pescare un bel po' di pesci.", "." },
  ["b43f6f8b734cc5f4"] = { "Ah ah, <ragazzo/ragazza>! L'⟦Alliance=Alleanza⟧ ha raccolto tutto quello che ci serve per far cominciare 'sta guerra! Magari l'⟦Horde=Orda⟧ ci raggiungerà presto?", "." },
  ["b441be4fc4ac985a"] = { "Cosa posso fare in una locanda?", "." },
  ["b44bab32e744813d"] = { "Miranda, puoi dirmi il costo in insegne degli oggetti che offri agli avventurieri con altre reputazioni?", "." },
  ["b44c1751136e43f8"] = { "Salve, amico. Cosa posso fare per te?", "." },
  ["b44ef09b0f0b6755"] = { "FATTO!", "." },
  ["b457c757291c4be6"] = { "Se fossi in te, comprerei un buono scommessa per la corsa goblin. Tifare per l'altra squadra è una perdita di tempo.", "." },
  ["b4596c56b1a43935"] = { "Mortali pietosi e prevedibili... Non sapete cosa avete fatto! La volontà del Padrone è compiuta. ⟦Moonglade=Radaluna⟧ sarà distrutta, e Malfurion con essa!", "." },
  ["b45abefe0dac33e5"] = { "Ah, ehm, sì, <signore/signora>. Pare che abbiamo raccolto tutto il Cuoio Medio che l'⟦Alliance=Alleanza⟧ ritiene necessario per la guerra. Mi dicono però che qui potrebbe esserci qualcun altro che ha ancora bisogno del tuo aiuto per la raccolta.", "." },
  ["b462dfab2f2de284"] = { "%s ruggisce, in cima ai ⟦Blackrock Spire=Bastioni di Roccianera⟧...", "." },
  ["b4677c1b23a584c5"] = { "Cerco addestramento da ladro.", "." },
  ["b46a258d0ed55e7a"] = { "{name}, abbiamo abbastanza rifornimenti per lanciare assalti di terra nel ⟦Field of Strife=Pian della Discordia⟧. Se vuoi inviare gli ordini, e il tuo grado è abbastanza alto, parla con il sergente Yazra Bloodsnarl nel ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧.", "." },
  ["b46a64f6e94ec6f8"] = { "Il potere della Luce è davvero grande e misericordioso.", "." },
  ["b46acb7719645ebb"] = { "Be', c'è un maestro dei grifoni su a ⟦Stormwind=Roccavento⟧, se devi volare da qualche parte. Dovresti vedere i grifoni atterrare alla tua destra mentre attraversi la ⟦Valley of Heroes=Valle degli Eroi⟧.", "." },
  ["b46c470ba18d1f4a"] = { "<Andorov ti guarda cupo.>\n\nSe sanguina, possiamo ucciderlo.", "." },
  ["b46d06adffb17880"] = { "È ora di prendere in mano la situazione. Vieni. Entra nel mio dominio e sfida la potenza del Flagello!", "." },
  ["b46d79175844e0fe"] = { "I mezzorsi Freddinverno che vivono qui a ⟦Winterspring=Fontefredda⟧ un tempo erano nostri alleati... Ma un giorno tutto cambiò.\n\nSpinti dalle strane pretese del loro gran capo, cominciarono ad attaccare chiunque incontrassero, compresa la nostra tribù. Ora se ne stanno per conto loro...", "." },
  ["b47df300f859831f"] = { "La fine si avvicina! Proprio mentre parliamo, i nostri rifornimenti vengono spediti a ⟦Silithus=Silitus⟧ e dovrebbero arrivare entro $2113w giorni. Una volta lì, non ho dubbi che verrà tutto assemblato in fretta, e poi aspetteremo che il gong risuoni ai cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per dare inizio alla guerra. Non vedo l'ora di analizzare se i nostri sforzi preparatori faranno la differenza.", "." },
  ["b483657db02e2621"] = { "Bevi qualcosa, {class}. Potrebbe essere l'ultima volta!", "." },
  ["b486c54b048a318a"] = { "Schiaccia!", "." },
  ["b4a3929ea49ff5d0"] = { "Ho sentito dire che a ⟦Stormwind=Roccavento⟧ c'è un nano che si è fatto una certa fama per la sua abilità nella caccia. Forse dovresti andare a vedere se può aiutarti.", "." },
  ["b4a8c64674b9040a"] = { "Come posso evocare Omen?", "." },
  ["b4aaa662c4d506ce"] = { "I recipienti muisek ora sono pronti, {name}.", "." },
  ["b4ac9661e327cb1b"] = { "Johnson? Credo che sia qui da qualche parte...", "." },
  ["b4acc52743f2c233"] = { "La corsa del Varcolargo partirà tra 1 minuto!", "." },
  ["b4acf49ca5a84db1"] = { "Salute, {name}. Sei <pronto/pronta> per l'addestramento?", "." },
  ["b4ae046ae3eb3ba9"] = { "<Benvenuto/Benvenuta> nella nostra tenda. Posso esserti utile?", "." },
  ["b4b13147ef3db3e4"] = { "Aprilo.", "." },
  ["b4b2691156796617"] = { "Com'è il filo della tua lama? Abbastanza affilato da squarciare la pancia del nemico? Lascia che ti mostri qualche trucco per renderlo ancora più tagliente.", "." },
  ["b4b490049a64ce5e"] = { "Grazie, Jessica.", "." },
  ["b4b8a298ed025e91"] = { "Noi molto più puliti di quegli ogre a Tanaris. Per tutto il deserto, a perdita d'occhio: cacca di ogre. Qui no, <signore/signora>, qui no!", "." },
  ["b4b9be2a3d7ce345"] = { "%s sembra parlare con lo scoiattolo e la statua. Di tanto in tanto indica nella tua direzione.", "." },
  ["b4c2699886d14a9d"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare gli ⟦Wild Leather Shoulders=Spallacci di Cuoio Selvatico⟧?", "." },
  ["b4cb149a91d09620"] = { "Il mio altare ti risucchierà la vita!", "." },
  ["b4ccba7ca72795c1"] = { "Sei tornat<o/a>. Splendido!\n\nCom'è andato il tuo viaggio a ⟦Silverpine=Pinargento⟧? Ti ci è voluto molto?\n\nMi è difficile capire se laggiù hai avuto successo, perché gran parte di quella terra è ormai corrotta. Il suo fetore soverchia qualunque bene tu possa aver fatto. Ma i piccoli successi a volte contano quanto quelli grandi. Purificare l'acqua laggiù è stato fondamentale per te e per tutti gli sciamani.", "." },
  ["b4d20a60c3b95163"] = { "Torna da ⟦Rau Cliffrunner=Rau Scalarupi⟧ al ⟦Freewind Post=Presidio di Ventolibero⟧ e riferiscigli cos'è successo.", "." },
  ["b4d8c598021c4a02"] = { "Non ho mai visto niente del genere! Guarda l'estensione della mandibola...", "." },
  ["b4da25df243d924e"] = { "Ehi! Smettila!", "." },
  ["b4dc8bc32bdf1f98"] = { "Ci sono due possibili risultati quando la matrice di sintesi dei Terrigeni si destabilizza. Avvio della rappresentazione visiva numero uno.\n\nLa prima matrice variante è un prodotto degenerativo della sintesi, qui designato con la nomenclatura comune di \"Trogg\". Questa variante mantiene forza e resistenza paragonabili a quelle dei Terrigeni, ma la sua capacità di elaborazione cognitiva è stata quasi del tutto compromessa. La forza di volontà e una spiccata astuzia sono gli unici fattori che guidano la psiche del trogg.", "." },
  ["b4e313d6361f6f3e"] = { "Chi osa sfidarmi nel mio dominio?!", "." },
  ["b4e7f4843c1d8373"] = { "Chi osa?! Ti distruggerò!", "." },
  ["b4edf195d8dbdd2f"] = { "Le nostre unità sono state promosse a campioni, ma posso ancora raccogliere altri rifornimenti.", "." },
  ["b4ef9550c59da1da"] = { "Ogni scarto riutilizzato ci rende meno spreconi e ci avvicina alla Madre Terra. Mooranta può mostrarti la via. Cercala appena fuori dagli armaioli di ⟦Thunder Bluff=Picco del Tuono⟧, sull'altura di mezzo.", "." },
  ["b4f4da810979ec90"] = { "Non puoi studiare le mie tecniche finché non hai imparato le basi. Parla con Kamari se ti interessa l'addestramento.", "." },
  ["b4ff5060ac194d9e"] = { "Un'armatura come quella che fai tu potrebbe fermare anche l'ascia più affilata. Mi hai colpito, {name}, e non succede spesso. Cerca un'Orchessa di nome ⟦Shayis Steelfury=Shayis Furiaferro⟧: fa le armature migliori fuori da quella maledetta roccaforte dei nani.", "." },
})
